<?php
// Fixture-only backup/restore helper. Never accepts production database names or a TCP connection.
declare(strict_types=1);
if(PHP_SAPI!=='cli'||!getenv('RUBIZH_TEST_MYSQL_SOCKET'))exit(1);
[$script,$mode,$name,$file]=$argv;
