if(!preg_match('/^fixture_[a-z0-9_]+$/D',$name)||$temp===false||$parent===false||($parent!==$temp&&!str_starts_with($parent,$temp.DIRECTORY_SEPARATOR))){fwrite(STDERR,"Fixture snapshot requires a fixture database and the system temporary directory.\n");exit(1);}
$db=new PDO('mysql:unix_socket='.getenv('RUBIZH_TEST_MYSQL_SOCKET').(in_array($mode,['backup','verify'],true)?';dbname='.$name:'').';charset=utf8mb4','root','',[PDO::ATTR_ERRMODE=>PDO::ERRMODE_EXCEPTION]);
if($mode==='backup'){$db->exec('SET TRANSACTION ISOLATION LEVEL REPEATABLE READ');$db->exec('START TRANSACTION WITH CONSISTENT SNAPSHOT');$data=['tables'=>[],'triggers'=>[]];foreach($db->query('SHOW FULL TABLES')->fetchAll(PDO::FETCH_NUM) as $t){if($t[1]!=='BASE TABLE')throw new RuntimeException('Unexpected view');$table=$t[0];$create=$db->query('SHOW CREATE TABLE `'.$table.'`')->fetch(PDO::FETCH_NUM)[1];$data['tables'][$table]=['create'=>$create,'rows'=>array_map(fn($r)=>array_map(fn($v)=>$v===null?null:base64_encode((string)$v),$r),$db->query('SELECT * FROM `'.$table.'`')->fetchAll(PDO::FETCH_ASSOC))];}foreach($db->query('SHOW TRIGGERS')->fetchAll(PDO::FETCH_ASSOC) as $t)$data['triggers'][]='CREATE TRIGGER `'.$t['Trigger'].'` '.$t['Timing'].' '.$t['Event'].' ON `'.$t['Table'].'` FOR EACH ROW '.$t['Statement'];$db->rollBack();file_put_contents($file,json_encode($data,JSON_THROW_ON_ERROR));chmod($file,0600);echo hash_file('sha256',$file);}
elseif($mode==='restore'){$data=json_decode((string)file_get_contents($file),true,512,JSON_THROW_ON_ERROR);$db->exec('CREATE DATABASE `'.$name.'` CHARACTER SET utf8mb4');$db->exec('USE `'.$name.'`');$db->exec('SET FOREIGN_KEY_CHECKS=0');foreach($data['tables'] as $table=>$t){$db->exec($t['create']);foreach($t['rows'] as $row){$columns=array_keys($row);$db->prepare('INSERT INTO `'.$table.'` (`'.implode('`,`',$columns).'`) VALUES ('.implode(',',array_fill(0,count($row),'?')).')')->execute(array_map(fn($v)=>$v===null?null:base64_decode($v,true),array_values($row)));}}$db->exec('SET FOREIGN_KEY_CHECKS=1');foreach($data['triggers'] as $sql)$db->exec($sql);echo json_encode(['restored_tables'=>count($data['tables']),'restored_triggers'=>count($data['triggers'])]);}elseif($mode==='verify'){$data=json_decode((string)file_get_contents($file),true,512,JSON_THROW_ON_ERROR);foreach($data['tables'] as $table=>$t){$actual=array_map(fn($r)=>json_encode(array_map(fn($v)=>$v===null?null:base64_encode((string)$v),$r),JSON_THROW_ON_ERROR),$db->query('SELECT * FROM `'.$table.'`')->fetchAll(PDO::FETCH_ASSOC));$expected=array_map(fn($r)=>json_encode($r,JSON_THROW_ON_ERROR),$t['rows']);sort($actual);sort($expected);if($actual!==$expected)throw new RuntimeException('Restore row mismatch: '.$table);}if(count($db->query('SHOW TRIGGERS')->fetchAll())!==count($data['triggers']))throw new RuntimeException('Trigger restore mismatch');echo json_encode(['verified_tables'=>count($data['tables']),'verified_triggers'=>count($data['triggers']),'all_rows_equal'=>true]);}else exit(1);
